import { loadCreateClient } from "./supabase-loader.js";
// esm.sh first, this site's own copy if that fails or hangs (supabase-loader.js).
const createClient = await loadCreateClient();

const cfg = window.TDW_CONFIG || {};
if (!cfg.supabaseUrl || cfg.supabaseUrl.includes("YOUR-PROJECT-REF")) {
  document.body.innerHTML = '<div style="padding:2rem;font-family:sans-serif">' +
    '<h2>Not configured</h2><p>Edit <code>config.js</code> with your Supabase project URL and publishable key, then redeploy.</p></div>';
  throw new Error("config.js not filled in");
}

// supabasePublishableKey replaces the old supabaseAnonKey - same client-side
// role (safe to expose, RLS still gates every table), new sb_publishable_...
// format instead of the legacy long-lived JWT anon token.
const sb = createClient(cfg.supabaseUrl, cfg.supabasePublishableKey, {
  auth: {
    storage: window.sessionStorage,
    persistSession: true,
    autoRefreshToken: true,
    // SaaS hardening (2026-09-29): true so a password-reset link
    // (sb.auth.resetPasswordForEmail -> e-mail -> back to this page) can
    // complete: supabase-js reads the recovery token off the URL on load and
    // emits PASSWORD_RECOVERY, handled in onAuthStateChange below. The
    // token is consumed and removed from the URL by the library; ledger
    // routing (#/auctions/...) is unaffected because a recovery URL carries
    // a different fragment shape.
    detectSessionInUrl: true
  }
});

// Which state this PAGE is - not a filter the user can toggle, a fact
// about which file loaded. public/index.html (FL) and public/tx.html (TX)
// are genuinely separate pages/URLs, each setting <body data-state="..">,
// specifically so the properties QUERY itself (see loadAll() below, which
// calls the get_properties(p_state, ...) RPC from
// 003_ledger_type_and_state_isolation.sql) is scoped server-side to one
// state - no "fetch everything, filter client-side" combined query, and no
// client-constructed request can accidentally omit the state scope, since
// p_state has no default and PostgREST rejects a call that omits it.
// Defaults to "FL" only for a stray direct load that skips the attribute
// (there shouldn't be one - both shipped pages set it).
//
// STATE_META is the one table of states this app has a page and assets
// for: the display name, the same-origin county basemap (the file the
// service worker precaches) and the city/zip label files. Every other
// state-dependent choice in this file reads it instead of an FL/TX ternary,
// so a future state is one row here (plus its real assets, a page and a
// MINIMAP_PROJ fit) - never a Florida asset standing in for it. A
// data-state naming a state NOT in this table is an error, not Florida:
// it is logged and the page falls back to FL only so the app still loads.
const STATE_META = {
  FL: { name: "Florida", page: "index.html", basemap: "fl-counties.svg", cities: "fl-cities.json", zips: "fl-zips.json" },
  TX: { name: "Texas", page: "tx.html", basemap: "tx-counties.svg", cities: "tx-cities.json", zips: "tx-zips.json" },
  // 2026-09-30 (state-expansion sprint): Louisiana publishes by PARISH. Its
  // city / ZIP label files do not exist yet - they 404 into the same
  // designed no-labels fallback tx-cities.json has always used.
  LA: { name: "Louisiana", page: "la.html", basemap: "la-parishes.svg", cities: "la-cities.json", zips: "la-zips.json", unit: "Parish", units: "parishes" },
  // 2026-09-30 (six-state expansion): basemaps generated by scripts/build_state_basemap.py
  // from us-atlas; no city / ZIP label files yet (the designed no-labels fallback).,
  MI: { name: "Michigan", page: "mi.html", basemap: "mi-counties.svg", cities: "mi-cities.json", zips: "mi-zips.json", assessedLabel: "State Equalized Value (county list)" },
  WY: { name: "Wyoming", page: "wy.html", basemap: "wy-counties.svg", cities: "wy-cities.json", zips: "wy-zips.json", marketLabel: "Total Value (county tax sale list)" },
  SC: { name: "South Carolina", page: "sc.html", basemap: "sc-counties.svg", cities: "sc-cities.json", zips: "sc-zips.json" },
  CO: { name: "Colorado", page: "co.html", basemap: "co-counties.svg", cities: "co-cities.json", zips: "co-zips.json", marketLabel: "Parcel Total Value (Colorado Public Parcels)" },
  WI: { name: "Wisconsin", page: "wi.html", basemap: "wi-counties.svg", cities: "wi-cities.json", zips: "wi-zips.json" },
  // 2026-10-04 (AVAILABLE expansion): one county AVAILABLE source each, collected for
  // admin use (UNREVIEWED); basemaps from scripts/build_state_basemap.py.
  MO: { name: "Missouri", page: "mo.html", basemap: "mo-counties.svg", cities: "mo-cities.json", zips: "mo-zips.json" },
  OK: { name: "Oklahoma", page: "ok.html", basemap: "ok-counties.svg", cities: "ok-cities.json", zips: "ok-zips.json" },
  PA: { name: "Pennsylvania", page: "pa.html", basemap: "pa-counties.svg", cities: "pa-cities.json", zips: "pa-zips.json" },
  MN: { name: "Minnesota", page: "mn.html", basemap: "mn-counties.svg", cities: "mn-cities.json", zips: "mn-zips.json" },
  // 2026-10-08 (Tennessee): the Shelby County Land Bank, collected for admin use (UNREVIEWED).
  TN: { name: "Tennessee", page: "tn.html", basemap: "tn-counties.svg", cities: "tn-cities.json", zips: "tn-zips.json" }
};
// Unified navigation (2026-09-30): the states a person can switch between are
// exactly STATE_META's keys - the states this app has a page, a basemap and
// production data for (tests/python pins them to harvesters/governance/
// states.PRODUCTION_STATES). Never a hard-coded "Florida".
const STATE_CODES = Object.keys(STATE_META);
const PAGE_STATE = (() => {
  const wanted = document.body.dataset.state;
  if (wanted && !STATE_META[wanted]) console.error(`Unsupported <body data-state="${wanted}"> - no page/basemap assets for it; rendering FL`);
  return STATE_META[wanted] ? wanted : "FL";
})();
const STATE_INFO = STATE_META[PAGE_STATE];
// The publishing unit every row on this page names: county (FL, TX) or
// parish (LA). A state page only ever holds its own state's rows.
const UNIT_WORD = STATE_INFO.unit || "County";
const UNITS_WORD = STATE_INFO.units || "counties";

// Internal build reference only (deploy verification, support requests) -
// deliberately not surfaced anywhere in the UI. Showing a raw "v7 -
// 2026-08-19" build tag in the header read as an unfinished/dev-mode
// artifact to end users, so the eyebrow below no longer includes it.
const BUILD = "v7 - 2026-08-19";
const IDLE_MINUTES = 5;

const DOC_STAMP_RATE = 0.007;
const RECORDING_FEE = 30;
const QUIET_TITLE_EST = 3000;
const TOP_PICK_RATIO = 12;
const SOON_DAYS = 14;
// "My Watchlist" is a small, deliberately-capped shortlist (separate from the
// unlimited ♥ Favorites) for the handful of properties actually being tracked
// - the cap forces prioritization instead of it turning into a second copy of
// the whole ledger.
//
// NAMING: this was "My Bid List" until 2026-09-02. Only the user-facing copy
// changed. The Supabase table is still `bid_list` and the 10-row cap is still
// enforced by a trigger on it (schema-v7-bidlist.sql) - both backend-owned -
// so the JS identifiers below (BIDLIST, BID_LIST_MAX, #bidListToggle, the
// data-action="bidlist" hooks) deliberately keep the old name and match the
// table rather than the label. Renaming them would put the front end and the
// schema out of step for no user-visible gain.
const BID_LIST_MAX = 10;

const GONE_HOURS_DEFAULT = 24;
const GONE_HOURS_FLAGGED = 48;
// The sync pipeline runs on a PC, not a server - nothing guarantees it ran
// today. Past this many hours since the newest row's updated_at, the "Data
// updated" line switches from a plain timestamp to a warning, since a quiet
// ledger and a dead sync both look identical otherwise.
const STALE_DATA_HOURS = 36;
// "closed" = left the county's "Auctions Waiting" feed after its sale date
// arrived, without a fresh harvest row to explain why (redeemed, canceled,
// or actually sold at the table - sync-harvest-to-supabase.ps1 can't tell
// which, since it only ever diffs against what's still listed, not against
// the county's separate "Closed or Canceled" page). Still counts as gone
// so the active badge reflects reality instead of a stale "active" pill
// sitting there long after the county's own site moved on.
const GONE_STATUSES = ["dropped", "sold", "notfound", "closed"];
const isGone = p => GONE_STATUSES.includes(p.status);

// WHY a sale closed is the first thing a bidder asks about a property that
// went away - redeemed by the owner, cancelled, or actually sold and for how
// much - and it changes what they do next. A redemption means the owner paid
// and the parcel is simply gone; a sale at 4x the opening bid tells you what
// that market really pays.
//
// The harvesters do not capture it yet: `status` only ever holds
// active/closed/dropped, and there is no column for the winning bid, so 361
// closed auction rows currently say nothing but "closed". Everything below
// reads `outcome` and `sold_price` defensively and falls back to today's
// behaviour, so it starts working the day the pipeline fills them in without
// another frontend change. See claude/closed-outcome-and-map-cities.md for
// the field spec.
const OUTCOME_LABEL = {
  sold: "Sold", "sold to third party": "Sold", "third party": "Sold",
  redeemed: "Redeemed", redemption: "Redeemed",
  cancelled: "Cancelled", canceled: "Cancelled", "cancelled by bank": "Cancelled by bank",
  "canceled by bank": "Cancelled by bank", bankruptcy: "Cancelled - bankruptcy",
  withdrawn: "Withdrawn", postponed: "Postponed", rescheduled: "Rescheduled",
  "struck to county": "Struck to county", county: "Struck to county",
  "no bid": "No bids", nobid: "No bids", "no bids": "No bids",
  "lands available": "Went to Lands Available", laft: "Went to Lands Available"
};

function outcomeText(p) {
  const raw = String(p.outcome == null ? "" : p.outcome).trim().toLowerCase();
  const label = OUTCOME_LABEL[raw] ||
    (raw ? raw.charAt(0).toUpperCase() + raw.slice(1) : "");
  const price = Number(p.sold_price);
  if (label === "Sold" && price > 0) return `Sold - ${fmtMoney(price)}`;
  if (label) return label;
  // Nothing recorded (no writer fills outcome/sold_price today, and neither
  // column is in get_properties). Launch-readiness correction (2026-09-26):
  // describe only what the pipeline observed - the listing disappeared from
  // the feed or list it was harvested from - and never imply sold, redeemed
  // or cancelled.
  return GONE_STATUS_TEXT[String(p.status || "").toLowerCase()] || "No longer listed";
}
const GONE_STATUS_TEXT = {
  closed: "No longer on the county's current auction feed",
  notfound: "No longer on the county-held list",
  dropped: "No longer listed"
};
const GONE_STATUS_CAVEAT = "The listing left the source feed or list after its date. Why (sold, redeemed, cancelled, postponed) is not recorded - check the county record.";
// The raw `status` column is a pipeline word (active/closed/dropped/
// notfound/available), not a customer word: "closed" used to render as-is
// and read as a closed sale. Rendered here as what the pipeline actually
// observed, with the caveat as the tooltip. The CSS class keeps the raw
// value so the existing colour rules still apply.
const STATUS_PILL_LABEL = { active: "Listed", available: "Listed", closed: "Left feed", dropped: "Left list", notfound: "Not on list" };
function cssEscape(v) { return (window.CSS && CSS.escape) ? CSS.escape(v) : String(v).replace(/["\\]/g, "\\$&"); }
function statusPillHtml(p) {
  const raw = String(p.status || "").toLowerCase();
  const label = STATUS_PILL_LABEL[raw] || raw || "Unknown";
  const tip = isGone(p) ? GONE_STATUS_CAVEAT : "On the source's list as of the last sync";
  return `<span class="pill ${esc(raw)}" title="${esc(tip)}">${esc(label)}</span>`;
}

