// the latest past sale event of each auction property (auction_events) and
// that event's latest "closed"-feed observation (the sale day's Closed or
// Canceled listing, read by scripts/auction_outcomes.py). null = not loaded
// (table missing); every reader then falls back to "not yet verified".
let AUCTION_OUTCOMES = null;
// Ids someone tried to add while the list was already full, in the order
// they tried - not persisted (in-memory/this session only), auto-promoted
// into BIDLIST oldest-first the moment a slot frees up. See promoteNextPending().
let BID_LIST_PENDING = [];

// The three ledgers are three different products that happen to share a
// filter bar - you bid against other people on one, buy at a fixed price on
// the second, and buy a lien rather than land on the third. They used to
// differ by a heading and nothing else, which is why Lands Available read as
// "the auctions page but emptier".
//
// Everything that makes a ledger feel like its own page is declared here:
// `slug` is its URL (#/lands), `icon` plus the --led-* palette in styles.css
// give it its own look, `how` says in one line what you actually DO on this
// page, and `empty` is what it says when there is nothing to show - which is
// a per-ledger question, since an empty auctions page and an empty
// certificates page mean different things.
// Each ledger's `tx` block overrides title/sub/how/empty when PAGE_STATE
// is "TX" (see ledgerCopy() below) - slug/icon stay shared since URL
// routing and the tab strip's visual identity don't need to change per
// state. The three Texas names come straight from the original roadmap
// request: Event Terminal (Sheriff/Constable sales) for the auction slot,
// OTC Catalog / Struck-Off Inventory for the laft slot, Yield Desk /
// Redeemable Tax Deeds for the certificate slot.
//
// KNOWN OPEN QUESTION, not silently resolved - see the frontend spec doc
// (claude/...-fl-tx-region-switcher.md): reusing the `certificate` ledger
// slot for Texas's "Yield Desk" is a surface-level fit (both are the
// third tab, both involve a redemption clock) but not a clean semantic
// match. FL's certificate is an unmatured LIEN accruing interest before
// any deed exists; TX's Yield Desk is a statutory redemption PREMIUM on a
// deed the investor already bought at a Sheriff/Constable sale. They are
// different instruments that happen to rhyme. Shipping this now (per
// "build now, empty is fine") rather than blocking on a fourth-ledger
// redesign - flagged here and in the spec doc for the next real look once
// actual TX Yield Desk rows exist to design against.
// Terminal-style line-icon set (Feather-style: 24x24 viewBox, stroke only,
// currentColor) - replaces the pictographic emoji this UI used to render
// inline. Swapping a name in ICON_PATHS re-skins every caller at once.
