// run synchronously during page init - before the script has reached the
// APP SHELL section - and render() calls renderShellExtras() on every pass,
// which reads this value.
let selectedPid = null;

// Customer monitoring (2026-10-01) - saved searches, alerts, server change
// events, analytics. Declared up here for the same TDZ reason as selectedPid:
// updateBadge()/render() can run during page init and reach track().
// `tables[name]` is null until probed, then true (present) or false (the
// migration that creates it - 024 - has not been applied: every feature
// degrades to an honest "not enabled on this deployment" or a browser-only
// fallback, never to a silent error).
const MONITOR = {
  tables: { saved_searches: null, user_alerts: null, alert_preferences: null, property_change_events: null, product_events: null },
  savedSearches: [], alerts: [], prefs: null, events: [], runs: null, loaded: false, searchTimer: null, queue: [], sessionTracked: false
};

// The Map page's own toolbar state (search/county/ledger/watchlist-only -
// see computeMapRows()/renderMapPage() in the "Map page (Phase 54)" section
// near the end of this file). Same TDZ reason as selectedPid just above:
// render() calls renderMapPage() on every pass and can run synchronously
// during page init, before the script has reached that section, and a
// `let` declared only down there stays in its temporal dead zone until
// that line runs - caught the same way selectedPid's bug was, by reading
// the console after the first cut of this section broke page load.
let mapFilter = { search: "", county: "ALL", ledger: "all", watchlistOnly: false, listFilters: true };

// Shell redesign (2026-10-04): global search / state picker UI state. Same
// TDZ reason as mapFilter - render() reaches renderListHead() during init.
let SHELL_UI = { gsTimer: null, gsActive: -1, gsMatches: [], picker: null };

function goneExpired(p) {
  if (!isGone(p) || !p.gone_since) return false;
  const flagged = FAVS.has(p.id) || (NOTES[p.id] || []).some(n => n.body || n.stage);
  const hours = flagged ? GONE_HOURS_FLAGGED : GONE_HOURS_DEFAULT;
  return (Date.now() - Date.parse(p.gone_since)) > hours * 3600 * 1000;
}

// An auction whose sale date has already come and gone is no longer open for
// bidding, no matter what the scraper's last-seen `status` says - that only
// flips to dropped/sold/notfound once a re-scrape happens to notice, which
// can lag days behind the actual sale. A passed calendar date isn't
// ambiguous the way a scrape-detected removal can be, so this doesn't wait
// for a grace period the way goneExpired() does for favorited/noted rows.
// LAFT and certificates aren't tied to a single sale date, so they're exempt.
function isPastDue(p) {
  if (p.source !== "auction") return false;
  const d = daysUntil(p);
  return d !== null && d < 0;
}

const fmtMoney = n => "$" + Number(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtShort = n => "$" + Math.round(Number(n)).toLocaleString("en-US");
const esc = s => String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));


// Which state a row belongs to. Defaults to "FL" for any row that predates
// the `properties.state` column (002_add_texas_support.sql) - same
// backward-compatibility default the column itself uses, kept here too so
// the frontend behaves correctly even a moment before that migration has
// actually been run against production.
const regionOf = p => (p && p.state) || "FL";

// ---- FL DOR property-use code labels ----
// Ported 1:1 from scripts/enrich_property_details.py's DOR_USE_LABELS /
// dor_use_to_prop_type() so the raw code stored in properties.dor_use_code
// (schema-v9-dor-use-code.sql) can be shown with the same label the backend
// already derives prop_type from, rather than a second, driftable copy of
// the mapping. Keep these two in sync if the Python side ever changes.
const DOR_USE_LABELS = {
  0: "Vacant Residential", 1: "Single Family", 2: "Mobile Home",
  3: "Multi-Family", 4: "Condo", 5: "Cooperative", 6: "Retirement Home",
  7: "Residential", 8: "Multi-Family", 9: "Residential Common Area",
  10: "Vacant Commercial", 39: "Hotel/Motel",
  40: "Vacant Industrial", 70: "Vacant Institutional",
  80: "Vacant Governmental"
};
function dorUseLabel(rawCode) {
  const code = parseInt(rawCode, 10);
  if (!Number.isFinite(code)) return null;
  if (code in DOR_USE_LABELS) return DOR_USE_LABELS[code];
  if (code >= 0 && code <= 9) return "Residential";
  if (code >= 10 && code <= 39) return "Commercial";
  if (code >= 40 && code <= 49) return "Industrial";
  if (code >= 50 && code <= 69) return "Agricultural";
  if (code >= 70 && code <= 79) return "Institutional";
  if (code >= 80 && code <= 89) return "Government";
  if (code >= 90 && code <= 99) return "Miscellaneous";
  return null;
}

// ---- TX Comptroller SPTB category labels ----
// Ported 1:1 from scripts/tx_use_codes.py's CODE_LABELS / category_label().
// Same caution applies here as in that module's docstring: individual CADs
// are NOT required to follow this list exactly - it's a reasonable
// statewide default, not a guarantee for any specific county.
const TX_CATEGORY_LABELS = {
  A: "Real, Residential", A1: "Single-Family Residential", A2: "Real, Residential, Mobile Home",
  B: "Real, Residential (Multi-Family)", B1: "Real, Residential, Multi-Family (2 units)",
  B2: "Real, Residential, Multi-Family (3-4 units)", B3: "Real, Residential, Multi-Family (5+ units)",
  B4: "Real, Residential, Multi-Family (Condominium)",
  C: "Vacant Lots / Land Tracts", C1: "Vacant Lots / Residential Tracts",
  C2: "Vacant Lots / Colonia Tracts", C3: "Vacant Lots / Commercial Tracts",
  D: "Agricultural / Open-Space Land", D1: "Qualified Open-Space / Agricultural Land",
  D2: "Non-Qualified (Non-Exempt) Agricultural Land / Timberland",
  E: "Farm & Ranch Improvements", E1: "Real, Farm & Ranch Improved",
  F: "Commercial / Industrial Real Property", F1: "Commercial Real Property",
  F2: "Industrial / Manufacturing Real Property",
  G: "Oil, Gas & Mineral Reserves", G1: "Oil & Gas Reserves", G2: "Other (Non-Oil/Gas) Minerals",
  J: "Utilities", J1: "Water Systems", J2: "Gas Companies", J3: "Electric Companies",
  J4: "Telephone Companies", J5: "Railroads", J6: "Pipelines", J7: "Cable Television Companies",
  L: "Commercial / Industrial Personal Property", L1: "Commercial Personal Property",
  L2: "Industrial & Manufacturing Personal Property",
  M: "Mobile / Other Tangible Personal Property", M1: "Tangible Other Personal, Mobile Homes",
  M2: "Tangible Other Personal, Travel Trailers", M3: "Tangible Other Personal, Watercraft",
  M4: "Tangible Other Personal, Aircraft",
  X: "Exempt Property", X0: "Exempt Property (Total)", X1: "Exempt - Government-Owned"
};
function txCategoryLabel(raw) {
  if (!raw) return null;
  const code = String(raw).trim().toUpperCase();
  if (!code) return null;
  if (code in TX_CATEGORY_LABELS) return TX_CATEGORY_LABELS[code];
  if (code[0] in TX_CATEGORY_LABELS) return TX_CATEGORY_LABELS[code[0]];
  return null;
}

// One small badge showing the state's own raw classification code + label -
// dor_use_code for FL, tx_category (raw SPTB code) for TX - reusing the
// .type-badge look the detail modal already has. Returns "" when there's
// nothing to show yet (not harvested/enriched), never a misleading
// "Unknown" the way the FDOR-derived prop_type badge does elsewhere.
function classificationBadgeHtml(p) {
  if (regionOf(p) === "TX") {
    if (!p.tx_category) return "";
    const label = txCategoryLabel(p.tx_category);
    return `<span class="type-badge" title="Texas Comptroller SPTB code - individual CADs aren't required to follow it exactly, verify per county">SPTB ${esc(p.tx_category)}${label ? " · " + esc(label) : ""}</span>`;
  }
  if (!p.dor_use_code) return "";
  const label = dorUseLabel(p.dor_use_code);
  return `<span class="type-badge">DOR ${esc(p.dor_use_code)}${label ? " · " + esc(label) : ""}</span>`;
}

// Shared error toast for the write actions below (favorite, hide, restore,
// watchlist, notes). These used to fail completely silently on a Supabase
// error - the button just re-enabled with zero indication anything went
// wrong. One small dismissable banner beats duplicating that logic five
// times, and beats a jarring native alert() (used for the admin-approval
// flow only, left as-is since that's a rarer, already-attention-grabbing
// action). Auto-hides; tap dismisses early.
let errToastTimer = null;
function showErrorToast(msg) {
  let el = document.getElementById("errToast");
  if (!el) {
    el = document.createElement("div");
    el.id = "errToast";
    el.className = "err-toast";
    // role="alert" (implicit aria-live="assertive") so a screen-reader user
    // is actually told a write action (favorite/hide/restore/note) failed -
    // previously this was silent to assistive tech, matching the visual
    // toast's own transient, no-action-required nature.
    el.setAttribute("role", "alert");
    el.addEventListener("click", hideErrorToast);
    document.body.appendChild(el);
  }
  el.textContent = msg;
  el.classList.add("show");
  clearTimeout(errToastTimer);
  errToastTimer = setTimeout(hideErrorToast, 5000);
}
function hideErrorToast() {
  const el = document.getElementById("errToast");
  if (el) el.classList.remove("show");
}

// Small icon-prefix for the quick-action reference links, shared by the
// compact card row and the roomier detail-modal buttons so the two stay
// visually consistent.
const LINK_ICON = {
  "Street View": "eye", "Google Maps search": "eye", "Appraiser": "building", "Zillow": "home", "Tax Collector": "dollar",
  "Auction": "gavel", "LAFT": "gavel", "Lands Available Listing": "gavel",
  "County Auction Site": "gavel", "County-Held Liens List": "clipboard", "Clerk Official Records": "doc",
  "Clerk of Courts": "scale", "GIS Map": "map"
};
const linkIcon = label => LINK_ICON[label] ? `<span class="link-icon">${svgIcon(LINK_ICON[label])}</span>` : "";

// Phase 35: provenance for reference links. Street View/Zillow are the only
// two with a client-side fallback (fallbackStreetviewUrl/fallbackZillowUrl
// above build a best-effort search URL when the harvester didn't supply a
// real one) - "estimated" here means exactly and only that: this link was
// guessed from the address string client-side, not confirmed by any
// source. A truthy p.url_streetview/p.url_zillow means the real, harvester-
// supplied link rendered instead, so no suffix. Every other link label
// (Appraiser, Tax Collector, Title Search, Clerk of Courts, GIS Map) is
// always a direct backend passthrough with no client construction (see
// detailHtml()/card() - only Street View and Zillow ever call a fallback
// builder), so they never get this suffix.
const isEstimatedLink = (label, p) =>
  label === "Google Maps search" || (label === "Street View" && !p.url_streetview) || (label === "Zillow" && !p.url_zillow);

// Small "ⓘ" tooltip affordance - keyboard-focusable (not hover-only) so it
// works on touch devices too. `tip` is plain text, escaped for the
// data-tip attribute the CSS ::after reads it from.
const infoTip = tip => `<i class="info-tip" tabindex="0" data-tip="${esc(tip)}">i</i>`;
const FEES_TIP = "Florida doc stamps (0.70/$100) + recording fee, added on top of whatever the actual winning bid turns out to be - estimated here using the opening bid, since the real winning bid isn't known in advance. On a homestead parcel the half-assessed amount is NOT added: F.S. 197.502(6)(c) puts it inside the opening bid already. Not shown for Lands Available parcels, whose added costs are itemised on the property page.";
// Phase 35: these three stats were already calculated, client-side, from
// raw county-sourced fields - they just had no infoTip() marking them as
// such, unlike Fees/Homestead/Accrued Interest/TDA Eligibility right below.
// Reusing the exact same infoTip() mechanism rather than inventing a new
// "calculated" UI pattern.
const EQUITY_SPREAD_TIP = "Calculated by this app: County Just/Assessed Value minus the opening bid. Not a profit estimate - it doesn't account for fees, repairs, municipal liens, or the real winning bid, which is usually higher than the opening bid.";
const WALK_AWAY_TIP = "Calculated by this app: County Just/Assessed Value times your ceiling % setting (in Filters). A number you choose, not a county figure and not a recommended bid.";
const BUILDING_VALUE_TIP = "Calculated by this app: County Just Value minus Land Value from the same tax roll. Not a separate appraisal - if the roll doesn't carry both figures, this is left off rather than guessed.";

// Properties synced from the statewide harvest pipeline (as opposed to the
// hand-researched watchlist) never get url_zillow / url_streetview from the
// sync script - the harvester doesn't collect them, so the column is left
// out of that upsert on purpose so it doesn't blank out a hand-researched
// link for the same property on a later re-sync. Build a best-effort search
// link from the address instead, client-side, only when the real one is
// missing - this never touches the database, so a hand-researched link
// (when one exists) always wins and is never at risk of being overwritten.
// Tax Collector / Title Search have no such generic URL - both are
// per-county lookups that need real research, so those stay blank until
// the data pipeline actually captures them.
function fallbackZillowUrl(p) {
  if (p.url_zillow) return p.url_zillow;
  // Zillow's own search doesn't take raw lat/long, only its address-search
  // form - so geocoding (see scripts/geocode_properties.py) can't sharpen
  // this one the way it does Street View below. Keep the address-search
  // fallback as-is.
  if (!p.address) return "";
  return `https://www.zillow.com/homes/${encodeURIComponent(p.address + ", " + p.county + " County, " + regionOf(p))}_rb/`;
}
// Launch-readiness correction (2026-09-26): unless a hand-researched
// url_streetview exists, the link below is a Google Maps SEARCH built by this
// app from the row's coordinates or address - not a Street View image and not
// a county record - so it is labelled for what it is.
function streetviewLinkLabel(p) { return p.url_streetview ? "Street View" : "Google Maps search"; }
function fallbackStreetviewUrl(p) {
  if (p.url_streetview) return p.url_streetview;
  // Prefer a direct coordinate link once geocode_properties.py has filled
  // these in (schema-v8-geocoding.sql) - lands on the actual parcel instead
  // of Google's best guess from an address search, which can miss on rural
  // routes, new subdivisions, or a scraped address with a typo.
  if (typeof p.latitude === "number" && typeof p.longitude === "number") {
    return `https://www.google.com/maps/search/?api=1&query=${p.latitude},${p.longitude}`;
  }
  if (!p.address) return "";
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.address + ", " + p.county + " County, " + regionOf(p))}`;
}

// ==================== property photos (Phase 51) ====================
// p.photo_url follows the NULL/''/real-value contract documented in
// scripts/fetch_property_photos.py: NULL = not checked yet, '' = checked,
// no Street View coverage there (common for vacant land), a real value =
// a cached public Supabase Storage image. Both non-real states render the
// exact same honest placeholder - the UI never distinguishes "haven't
// looked yet" from "looked, nothing there" because neither is a photo, and
// pretending otherwise (a fake stock house image, a broken <img>) would be
// worse than a plain placeholder in both cases.
function hasPhoto(p) { return typeof p.photo_url === "string" && p.photo_url.length > 0; }
// cls picks the size via CSS (card vs. detail-hero) - one markup shape,
// two presentations, same pattern as photoOrPlaceholder's callers below.
// Phase 66: the two "no photo" states are told apart in WORDS only - same
// slim bar, same icon, no broken-image look for either:
//   photo_url NULL -> the photo pipeline has not looked at this address yet
//   photo_url ''   -> it looked, and Google has no Street View coverage here
//                     (common for vacant land / rural parcels) - a photo is
//                     not coming, and saying "not available" would imply
//                     one should exist.
// Both come straight from the NULL/''/value contract documented on
// properties.photo_url (CLAUDE.md, "Property photos") - nothing inferred.
// Launch-readiness correction (2026-09-26): '' can be written by EITHER image
// pipeline (the USDA NAIP enricher or the Street View fetcher) when it finds
// nothing, so the wording must not name one provider. Measured 2026-09-26:
// every stored photo_url in production has photo_source = 'usda_naip' (an
// overhead aerial) and none is a Street View still.
function photoStateText(p) {
  return p.photo_url === "" ? "Checked - no stored image for this address" : "Image not checked yet";
}
// What the stored image IS, from photo_source (migration 011), never assumed.
// NAIP is an overhead aerial of the area around the coordinates - not a
// photo of the building, not street-level, and not current condition.
const PHOTO_SOURCE_LABELS = { usda_naip: "Aerial image · USDA NAIP", google_streetview: "Street View" };
function photoCaption(p) {
  const base = PHOTO_SOURCE_LABELS[p.photo_source] || "Stored image · source not recorded";
  const year = Number(p.photo_captured_year);
  return year > 0 ? `${base} · ${year}` : base;
}
function photoAlt(p) {
  return p.photo_source === "usda_naip" ? "Overhead aerial image of the area around this property (USDA NAIP)"
    : p.photo_source === "google_streetview" ? "Street-level image near this address (Google Street View)"
    : "Stored image for this property";
}
function photoOrPlaceholder(p, cls) {
  if (hasPhoto(p)) {
    // The caption names what the image IS, read from photo_source, so an
    // aerial is never presented as a street-level or listing photo.
    return `<div class="${cls} has-photo" data-photo-source="${esc(p.photo_source || "unknown")}"><img src="${esc(p.photo_url)}" alt="${esc(photoAlt(p))}" loading="lazy" width="640" height="400"><span class="photo-caption" title="Imagery may be years old and does not show current condition.">${esc(photoCaption(p))}</span></div>`;
  }
  // Compact bar, not a full-size empty photo box - see the CSS comment on
  // .prop-card-photo.no-photo. Most rows don't have a cached photo yet
  // (the harvest pipeline is real but not activated - see CLAUDE.md's
  // "Property photos" section), and a blank photo-sized rectangle on every
  // single card would waste far more space than the honest small "no photo"
  // strip this renders instead.
  return `<div class="${cls} no-photo">${svgIcon(isBareLand(p) ? "layers" : "building")}<span>${esc(photoStateText(p))}</span></div>`;
}

// ==================== Phase 67: property visual hierarchy ====================
// One deterministic ladder, decided from real fields only, and each rung
// labelled for what it IS so a reader can never mistake one for another:
//   1. a stored image (photo_url), captioned from          -> "Aerial image ·
//      photo_source (NAIP aerial or Street View still)         USDA NAIP" etc.
//   2. a provider's static satellite image centred on the   -> "Satellite ·
//      row's own coordinates (MapTiler Static Maps API, or     MapTiler/Google"
//      Google Maps Static API) - only with coordinates AND a
//      configured key, requested lazily, one per card in view
//   3. the app's own county outline with the coordinate    -> "Location in
//      dotted on it (same-origin SVG, no third party)          <county> County"
//   4. a restrained placeholder naming both absences        -> "Image not
//      (photo state + not yet geocoded)                        checked yet ·
//                                                              Not yet geocoded"
// Never a generated "property photo", never a boundary the backend doesn't
// have (there is no parcel geometry anywhere in this app), never a map
// centred on a guessed location. The two third-party rungs send the row's
// coordinates to that provider - the same trade-off Marc accepted for the
// satellite basemaps (CLAUDE.md Phase 55/56), now applied per card; both
// images carry the provider's own attribution baked in (MapTiler's static
// endpoint renders "© MapTiler © OpenStreetMap contributors" in-image by
// default; Google's renders its logo and "Map data ©"), plus the caption.
// Licensing: MapTiler Static Maps is part of the free plan and allows
// display in a web app with attribution; Google Maps Static API requires
// the key's project to have that API enabled and bills per load - it is
// the SECOND choice here for that reason and because the Demo Key in use
// is testing-only (config.js). Neither image is cached or stored by this
// app; each is a plain <img> the browser fetches on demand.
const STATIC_IMG_W = 640, STATIC_IMG_H = 320, STATIC_IMG_ZOOM = 17;
function staticImageUrl(p, cfg) {
  const c = cfg || window.TDW_CONFIG || {};
  if (!(hasNum(p.latitude) && hasNum(p.longitude))) return null;
  const lat = Number(p.latitude).toFixed(6), lng = Number(p.longitude).toFixed(6);
  const mt = typeof c.maptilerKey === "string" ? c.maptilerKey.trim() : "";
  if (mt) {
    return {
      provider: "maptiler", label: "Satellite · MapTiler",
      url: `https://api.maptiler.com/maps/hybrid/static/${lng},${lat},${STATIC_IMG_ZOOM}/${STATIC_IMG_W}x${STATIC_IMG_H}.png?markers=${lng},${lat},red&key=${encodeURIComponent(mt)}`
    };
  }
  const g = typeof c.googleMapsApiKey === "string" ? c.googleMapsApiKey.trim() : "";
  if (g) {
    return {
      provider: "google", label: "Satellite · Google",
      url: `https://maps.googleapis.com/maps/api/staticmap?center=${lat},${lng}&zoom=${STATIC_IMG_ZOOM}&size=${STATIC_IMG_W}x${STATIC_IMG_H}&scale=2&maptype=hybrid&markers=color:red%7C${lat},${lng}&key=${encodeURIComponent(g)}`
    };
  }
  return null;
}
// `cls` is the caller's size class (prop-card-photo / detail-hero-photo /
// pv-visual). The Map page's preview ("pv-visual") skips rungs 3-4: the
// map beside it already IS the location context, and its own Location line
// says "not yet geocoded" in words.
// ==================== live NAIP imagery (2026-10-05) ====================
// The same rules as harvesters/imagery (a test pins the constants): USDA NAIP
// aerial imagery, public domain, requested straight from USGS The National
// Map for the record's OWN coordinates - the same square the stored-image
// pipeline frames, so nothing is stored and no budget is spent. Lazy, one
// request per card in view; a thumbnail on lists, a larger image on the
// property page. It sits after a stored image and before the key-based
