var COUNTY_STEP_STATE_LABELS = COUNTY_STEP_STATE_LABELS || { VERIFIED: "Verified", PARTIAL: "Partly verified", NOT_VERIFIED: "Not yet verified", NOT_APPLICABLE: "Not applicable" };
