    source_publication: review ? "review" : "approved",
    source_health: health,
    acq_path: a.verified ? "verified" : (ev && ev.status === "UNAVAILABLE" ? "unavailable" : "not_verified"),
    acq_url: !!(a.verified && (a.applicationUrl || a.url)),
