  if (clear) clear.hidden = !q;
  SHELL_UI.gsActive = -1;
  if (q.length < GS_MIN) { box.hidden = true; input.setAttribute("aria-expanded", "false"); box.innerHTML = ""; return; }
  box.hidden = false;
  input.setAttribute("aria-expanded", "true");
